 @code {
     private List<TaskItem> allTasks = new();
     private bool isLoading = true;
     private string? errorMessage;
     private string searchText = string.Empty;

     private const string StatusToDo = "To Do";
     private const string StatusInProgress = "In Progress";
     private const string StatusDone = "Done";
     private static readonly string[] Statuses = { StatusToDo, StatusInProgress, StatusDone };

     private List<TaskItem> todoTasks => allTasks.Where(t => t.Status == StatusToDo).ToList();
     private List<TaskItem> inProgressTasks => allTasks.Where(t => t.Status == StatusInProgress).ToList();
     private List<TaskItem> doneTasks => allTasks.Where(t => t.Status == StatusDone).ToList();
     private int overdueTasks => allTasks.Count(t => t.DueDate < DateTime.Today && t.Status != StatusDone);

     private List<TaskItem> filteredTodo => Filter(todoTasks);
     private List<TaskItem> filteredInProgress => Filter(inProgressTasks);
     private List<TaskItem> filteredDone => Filter(doneTasks);

     private List<TaskItem> Filter(List<TaskItem> tasks)
     {
         if (string.IsNullOrWhiteSpace(searchText))
             return tasks;
         return tasks.Where(t => t.Title.Contains(searchText, StringComparison.OrdinalIgnoreCase)).ToList();
     }

     protected override async Task OnInitializedAsync()
     {
         try
         {
             allTasks = await TaskService.GetAllTasksAsync();
         }
         catch (Exception ex)
         {
             errorMessage = $"Failed to load tasks: {ex.Message}";
         }
         finally
         {
             isLoading = false;
         }
     }

     private void OnSearchChanged(string value)
     {
         searchText = value;
     }

     private async Task MoveTask(TaskItem task, KanbanColumn.MoveDirection direction)
     {
         var currentIndex = Array.IndexOf(Statuses, task.Status);
         var newIndex = direction == KanbanColumn.MoveDirection.Left ? currentIndex - 1 : currentIndex + 1;

         if (newIndex < 0 || newIndex >= Statuses.Length)
             return;

         var newStatus = Statuses[newIndex];

         try
         {
             await TaskService.UpdateTaskStatusAsync(task.Id, newStatus);
             var index = allTasks.FindIndex(t => t.Id == task.Id);
             if (index >= 0)
             {
                 allTasks[index] = task with { Status = newStatus };
             }
         }
         catch (Exception ex)
         {
             errorMessage = $"Failed to move task: {ex.Message}";
         }
     }

     private async Task AddTask((string Title, string Assignee, string Priority, DateTime DueDate) data, string status)
     {
         try
         {
             var newTask = await TaskService.CreateTaskAsync(data.Title, data.Assignee, data.Priority, data.DueDate);
             allTasks.Add(newTask with { Status = status });
         }
         catch (Exception ex)
         {
             errorMessage = $"Failed to add task: {ex.Message}";
         }
     }
 }

